/** Pick a language from ?lang=, the saved choice, the browser languages, then the time-zone region (no network lookup). */
window.CUDE_PICK_LANG = function (supported) {
  var q = new URLSearchParams(location.search).get('lang');
  if (q && supported.indexOf(q) >= 0) return q;
  try { var s = localStorage.getItem('cude-lang'); if (s && supported.indexOf(s) >= 0) return s; } catch (e) {}
  var langs = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']);
  // A non-English browser language is a clear choice; English is often just the default, so the region decides then.
  for (var i = 0; i < langs.length; i++) { var base = String(langs[i] || '').toLowerCase().split('-')[0]; if (base !== 'en' && supported.indexOf(base) >= 0) return base; }
  var tz = ''; try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch (e) {}
  var byZone = { 'Europe/Istanbul': 'tr', 'Asia/Istanbul': 'tr', 'Europe/Berlin': 'de', 'Europe/Vienna': 'de', 'Europe/Zurich': 'de', 'Europe/Paris': 'fr', 'Europe/Brussels': 'fr', 'Europe/Madrid': 'es', 'America/Mexico_City': 'es', 'America/Bogota': 'es', 'America/Argentina/Buenos_Aires': 'es', 'Europe/Lisbon': 'pt', 'America/Sao_Paulo': 'pt', 'Europe/Moscow': 'ru', 'Asia/Riyadh': 'ar', 'Asia/Dubai': 'ar', 'Africa/Cairo': 'ar', 'Asia/Baghdad': 'ar' };
  return byZone[tz] && supported.indexOf(byZone[tz]) >= 0 ? byZone[tz] : 'en';
};
